import { createChart, removeChart } from '../test/ut/core/utHelper';
import { registerMap } from '../src/echarts.all';
import GeoModel from '../src/coord/geo/GeoModel';
import MapSeries from '../src/chart/map/MapSeries';
import { EChartsType } from '../src/echarts.all';

function makeGeoJSON() {
    return {
        type: 'FeatureCollection',
        features: [
            {
                type: 'Feature',
                properties: {
                    name: 'styledRegion',
                    echartsStyle: {
                        itemStyle: {
                            areaColor: '#f00'
                        },
                        label: {
                            show: true,
                            color: 'blue'
                        },
                        emphasis: {
                            itemStyle: {
                                areaColor: 'purple'
                            }
                        }
                    }
                },
                geometry: {
                    type: 'Polygon',
                    coordinates: [[[0, 0], [10, 0], [10, 10], [0, 10], [0, 0]]]
                }
            },
            {
                type: 'Feature',
                properties: {
                    name: 'plainRegion'
                },
                geometry: {
                    type: 'Polygon',
                    coordinates: [[[20, 0], [30, 0], [30, 10], [20, 10], [20, 0]]]
                }
            },
            {
                type: 'Feature',
                properties: {
                    name: 'overriddenRegion',
                    echartsStyle: {
                        itemStyle: {
                            areaColor: '#000'
                        }
                    }
                },
                geometry: {
                    type: 'Polygon',
                    coordinates: [[[40, 0], [50, 0], [50, 10], [40, 10], [40, 0]]]
                }
            }
        ]
    } as any;
}

describe('geojson-region-styling', function () {

    let chart: EChartsType;

    afterEach(function () {
        chart && removeChart(chart);
        chart = null;
    });

    it('geo component applies echartsStyle from GeoJSON feature properties', function () {
        registerMap('geojsonRegionStylingGeo', makeGeoJSON());
        chart = createChart();
        chart.setOption({
            geo: {
                map: 'geojsonRegionStylingGeo'
            }
        });

        const geoModel = chart.getModel().getComponent('geo', 0) as GeoModel;

        const styledRegionModel = geoModel.getRegionModel('styledRegion');
        expect(styledRegionModel.get(['itemStyle', 'areaColor'])).toBe('#f00');
        expect(styledRegionModel.get(['label', 'show'])).toBe(true);
        expect(styledRegionModel.get(['label', 'color'])).toBe('blue');
        expect(styledRegionModel.get(['emphasis', 'itemStyle', 'areaColor'])).toBe('purple');

        // Regions without echartsStyle stay untouched.
        const plainRegionModel = geoModel.getRegionModel('plainRegion');
        expect(plainRegionModel.option).toEqual({ name: 'plainRegion' });
    });

    it('explicit geo.regions option takes precedence over echartsStyle', function () {
        registerMap('geojsonRegionStylingGeoOverride', makeGeoJSON());
        chart = createChart();
        chart.setOption({
            geo: {
                map: 'geojsonRegionStylingGeoOverride',
                regions: [{
                    name: 'styledRegion',
                    itemStyle: {
                        areaColor: '#0f0'
                    }
                }]
            }
        });

        const geoModel = chart.getModel().getComponent('geo', 0) as GeoModel;
        const regionModel = geoModel.getRegionModel('styledRegion');
        // Explicit region option wins on the keys it declares...
        expect(regionModel.get(['itemStyle', 'areaColor'])).toBe('#0f0');
        // ...while echartsStyle still fills in the keys it does not declare.
        expect(regionModel.get(['label', 'show'])).toBe(true);
        expect(regionModel.get(['label', 'color'])).toBe('blue');
    });

    it('map series applies echartsStyle and data item option wins', function () {
        registerMap('geojsonRegionStylingMap', makeGeoJSON());

        registerMap('geojsonRegionStylingMap', makeGeoJSON());
        chart = createChart();
        chart.setOption({
            series: [{
                type: 'map',
                map: 'geojsonRegionStylingMap',
                data: [
                    { name: 'overriddenRegion', value: 1, itemStyle: { areaColor: 'cyan' } }
                ]
            }]
        });

        const seriesModel = chart.getModel().getSeriesByIndex(0) as MapSeries;
        const data = seriesModel.getData();

        // Region missing from series data is appended with echartsStyle applied.
        const styledIdx = data.indexOfName('styledRegion');
        expect(styledIdx).toBeGreaterThanOrEqual(0);
        const styledItem = data.getRawDataItem(styledIdx) as any;
        expect(styledItem.itemStyle.areaColor).toBe('#f00');
        expect(styledItem.label.show).toBe(true);
        expect(styledItem.emphasis.itemStyle.areaColor).toBe('purple');

        // echartsStyle fills defaults but does not override the data item option.
        const overriddenIdx = data.indexOfName('overriddenRegion');
        expect(overriddenIdx).toBeGreaterThanOrEqual(0);
        const overriddenItem = data.getRawDataItem(overriddenIdx) as any;
        expect(overriddenItem.itemStyle.areaColor).toBe('cyan');

        // Region without echartsStyle keeps a bare data item.
        const plainIdx = data.indexOfName('plainRegion');
        expect(plainIdx).toBeGreaterThanOrEqual(0);
        expect(data.getRawDataItem(plainIdx)).toEqual({ name: 'plainRegion' });
    });
});

