/*
* Safeguarding test for requirement: map-regions-silent
* Verifies that `regions[].silent` is honored per-region for both the
* geo component and series.map rendering, and that silent specified in
* GeoJSON `echartsStyle` survives map data refreshes.
*/

import { createChart, removeChart } from '../test/ut/core/utHelper';
import { registerMap, EChartsType } from '../src/echarts.all';
import GeoModel from '../src/coord/geo/GeoModel';

function makeGeoJSON(withEchartsStyle?: boolean) {
    return {
        type: 'FeatureCollection',
        features: [
            {
                type: 'Feature',
                properties: withEchartsStyle
                    ? { name: 'regionA', echartsStyle: { silent: true } }
                    : { name: 'regionA' },
                geometry: {
                    type: 'Polygon',
                    coordinates: [[[0, 0], [10, 0], [10, 10], [0, 10], [0, 0]]]
                }
            },
            {
                type: 'Feature',
                properties: { name: 'regionB' },
                geometry: {
                    type: 'Polygon',
                    coordinates: [[[20, 0], [30, 0], [30, 10], [20, 10], [20, 0]]]
                }
            }
        ]
    } as any;
}

function isSilentWithAncestors(el: any): boolean {
    let cur = el;
    while (cur) {
        if (cur.silent) {
            return true;
        }
        cur = cur.parent;
    }
    return false;
}

function getPolygons(chart: EChartsType): any[] {
    const list = (chart.getZr() as any).storage.getDisplayList() as any[];
    return list.filter(el => el.type === 'polygon' || el.type === 'compound-path');
}

describe('map-regions-silent', function () {

    let chart: EChartsType;

    afterEach(function () {
        chart && removeChart(chart);
        chart = null;
    });

    it('geo regions[].silent is exposed on the region model', function () {
        registerMap('regionsSilentGeoModel', makeGeoJSON());
        chart = createChart();
        chart.setOption({
            geo: {
                map: 'regionsSilentGeoModel',
                regions: [{ name: 'regionA', silent: true }]
            }
        });

        const geoModel = chart.getModel().getComponent('geo', 0) as GeoModel;
        expect(geoModel.getRegionModel('regionA').get('silent', true)).toBe(true);
        expect(geoModel.getRegionModel('regionB').get('silent', true)).toBeUndefined();
    });

    it('geo regions[].silent makes only the targeted region non-interactive', function () {
        registerMap('regionsSilentGeo', makeGeoJSON());
        chart = createChart();
        chart.setOption({
            geo: {
                map: 'regionsSilentGeo',
                regions: [{ name: 'regionA', silent: true }]
            }
        });

        const polygons = getPolygons(chart);
        expect(polygons.length).toBeGreaterThanOrEqual(2);
        const silentCount = polygons.filter(isSilentWithAncestors).length;
        // Only regionA is silent; regionB keeps responding normally.
        expect(silentCount).toBeGreaterThanOrEqual(1);
        expect(silentCount).toBeLessThan(polygons.length);
    });

    it('series.map data item silent makes only the targeted region non-interactive', function () {
        registerMap('regionsSilentMap', makeGeoJSON());
        chart = createChart();
        chart.setOption({
            series: [{
                type: 'map',
                map: 'regionsSilentMap',
                data: [
                    { name: 'regionA', value: 1, silent: true },
                    { name: 'regionB', value: 2 }
                ]
            }]
        });

        const polygons = getPolygons(chart);
        expect(polygons.length).toBeGreaterThanOrEqual(2);
        const silentCount = polygons.filter(isSilentWithAncestors).length;
        expect(silentCount).toBeGreaterThanOrEqual(1);
        expect(silentCount).toBeLessThan(polygons.length);
    });

    it('silent in GeoJSON echartsStyle is preserved after map data load', function () {
        registerMap('regionsSilentGeoJSONStyle', makeGeoJSON(true));
        chart = createChart();
        chart.setOption({
            geo: {
                map: 'regionsSilentGeoJSONStyle'
            }
        });

        const geoModel = chart.getModel().getComponent('geo', 0) as GeoModel;
        expect(geoModel.getRegionModel('regionA').get('silent', true)).toBe(true);

        const polygons = getPolygons(chart);
        const silentCount = polygons.filter(isSilentWithAncestors).length;
        expect(silentCount).toBeGreaterThanOrEqual(1);
        expect(silentCount).toBeLessThan(polygons.length);
    });
});

